"""Figures for cusp-size. DRAFT."""
import numpy as np, json, matplotlib; matplotlib.use("Agg"); import matplotlib.pyplot as plt
plt.rcParams.update({"font.size": 10}); s = json.load(open("scan.json")); c = json.load(open("compare.json"))
t = np.array(s["t"]); F = np.array([complex(*v) for v in s["F"]]); T = np.array([complex(*v) for v in s["true"]]); A = np.array([complex(*v) for v in s["A"]])
fig, ax = plt.subplots(2, 1, figsize=(10, 7), sharex=True)
a = ax[0]; a.plot(t, abs(T), color="0.2", lw=2.5, label="target: |ζ(β−1)/ζ(β)| (Knauf's limit, continued to the line)")
a.plot(t, abs(F), color="tab:orange", lw=1.2, ls="--", label="chains of length 17 to 33 with the cusp tail fitted out")
for g in [14.13, 21.02, 25.01, 30.42, 32.94, 37.59, 40.92, 43.33]: a.axvline(g, color="tab:blue", lw=0.6, ls=":")
a.set_ylabel("size on the line Re β = 3/2"); a.legend(fontsize=8.5, loc="upper left"); a.set_ylim(0, 3.2)
a.set_title("A1. Fitting out the cusp turns finite chains into Knauf's limit along the whole line (dotted: ζ's zeros)", fontsize=10)
b = ax[1]; tc = np.array(c["t"])
b.plot(tc, c["single"], color="tab:red", label="one chain, length 33"); b.plot(tc, c["cusp2"], color="tab:orange", label="cusp tail fitted out (lengths 17 to 33)")
b.set_yscale("log"); b.set_xlabel("height t (β = 3/2 + it)"); b.set_ylabel("distance from the target"); b.legend(fontsize=8.5)
b.set_title("A2. The miss drops from about 0.025 to about 0.001 (median over the line)", fontsize=10)
fig.tight_layout(); fig.savefig("figures/figA_limit_recovered.png", dpi=150); plt.close(fig)
fig, ax = plt.subplots(figsize=(10, 3.6)); ax.plot(t, abs(A), color="tab:purple")
for g in [14.13, 21.02, 25.01, 30.42, 32.94, 37.59, 40.92, 43.33]: ax.axvline(g, color="tab:blue", lw=0.6, ls=":")
ax.set_xlabel("height t"); ax.set_ylabel("cusp size |A|"); ax.set_title("B. The cusp's size along the line: not zero at ζ's zeros, and not yet matched to any ζ formula", fontsize=10)
fig.tight_layout(); fig.savefig("figures/figB_cusp_size.png", dpi=150); plt.close(fig); print("done")
